import React, { useState } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const EmployeeList = () => {
  const [showChart, setShowChart] = useState(false);

  const employees = [
    {
      id: 1,
      name: "Alice",
      role: "Developer",
      location: "Hyderabad",
      date: "2026-01-15",
      salary: 60000,
      photo: "https://via.placeholder.com/50",
    },
    {
      id: 2,
      name: "Bob",
      role: "Designer",
      location: "Mumbai",
      date: "2025-12-10",
      salary: 55000,
      photo: "https://via.placeholder.com/50",
    },
    {
      id: 3,
      name: "Charlie",
      role: "Manager",
      location: "Bangalore",
      date: "2024-09-05",
      salary: 80000,
      photo: "https://via.placeholder.com/50",
    },
  ];

  const handleViewSalaryChart = () => {
    setShowChart(true);
  };

  // Prepare chart data
  const chartData = {
    labels: employees.map((e) => e.name),
    datasets: [
      {
        label: "Salary",
        data: employees.map((e) => e.salary),
        backgroundColor: "rgba(75, 192, 192, 0.6)",
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: { position: "top" },
      title: { display: true, text: "Employee Salary Chart" },
    },
  };

  return (
    <div>
      <h1>Employee List</h1>
      <button onClick={handleViewSalaryChart}>View Salary Chart</button>
      <button onClick={() => setShowChart(false)}>Hide Chart</button>

      <table border="1" cellPadding="8" style={{ marginTop: "20px" }}>
        <thead>
          <tr>
            <th>Photo</th>
            <th>Name</th>
            <th>Role</th>
            <th>Location</th>
            <th>ID</th>
            <th>Date</th>
            <th>Salary</th>
          </tr>
        </thead>
        <tbody>
          {employees.map((emp) => (
            <tr key={emp.id}>
              <td>
                <img src={emp.photo} alt={emp.name} width="50" height="50" />
              </td>
              <td>{emp.name}</td>
              <td>{emp.role}</td>
              <td>{emp.location}</td>
              <td>{emp.id}</td>
              <td>{emp.date}</td>
              <td>{emp.salary}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {showChart && (
        <div style={{ width: "70%", marginTop: "30px" }}>
          <Bar data={chartData} options={chartOptions} />
        </div>
      )}
    </div>
  );
};

export default EmployeeList;
